// Adapted from Zard UI 1.1.1 (MIT) — https://github.com/zard-ui/zardui
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  ElementRef,
  inject,
  input,
} from "@angular/core";
import { NgIcon } from "@ng-icons/core";
import { lucideLoaderCircle } from "@ng-icons/lucide";
import type { VariantProps } from "class-variance-authority";
import { buttonVariants } from "@/ui/primitives/button-variants";
import { cn } from "@/ui/utils";

type ButtonVariants = VariantProps<typeof buttonVariants>;

/**
 * The app button, on a native `<button>` or `<a>`. Prefer icon + text for actions, and keep the
 * label stable while loading. On an anchor, `disabled` sets `aria-disabled` and drops the tab stop.
 */
@Component({
  selector: "button[koButton], a[koButton]",
  imports: [NgIcon],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    "[class]": "classes()",
    "[attr.disabled]": "isButton && inactive() ? '' : null",
    "[attr.aria-busy]": "loading() ? 'true' : null",
    "[attr.aria-disabled]": "inactive() ? 'true' : null",
    "[attr.tabindex]": "!isButton && inactive() ? -1 : tabindex()",
    "(click)": "onClick($event)",
  },
  template: `
    @if (icon(); as svg) {
      <ng-icon
        aria-hidden="true"
        size="1rem"
        [svg]="loading() ? spinner : svg"
        [class.animate-spin]="loading()"
        [class.motion-reduce:animate-none]="loading()"
      />
    }
    <span
      class="inline-flex items-center justify-center gap-2"
      [class.opacity-0]="loading() && !icon()"
    >
      <ng-content />
    </span>
    @if (loading() && !icon()) {
      <ng-icon
        aria-hidden="true"
        size="1rem"
        class="absolute animate-spin motion-reduce:animate-none"
        [svg]="spinner"
      />
    }
  `,
})
export class KoButton {
  readonly variant = input<ButtonVariants["variant"]>("default");
  readonly size = input<ButtonVariants["size"]>("default");
  readonly icon = input<string>();
  readonly loading = input(false, { transform: booleanAttribute });
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly class = input<string>("");
  /** Re-reads a static `tabindex` so the host binding never strips it from an enabled control. */
  readonly tabindex = input<string | number | null>(null);

  protected readonly spinner = lucideLoaderCircle;
  protected readonly isButton =
    inject<ElementRef<HTMLElement>>(ElementRef).nativeElement.tagName === "BUTTON";
  protected readonly inactive = computed(() => this.disabled() || this.loading());
  protected readonly classes = computed(() =>
    cn(
      buttonVariants({ variant: this.variant(), size: this.size() }),
      this.loading() && "disabled:!opacity-100",
      this.class(),
    ),
  );

  protected onClick(event: Event): void {
    if (this.inactive()) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }
}

/** Compact toolbar action with a required accessible name and native tooltip. */
@Component({
  selector: "button[koIconButton]",
  imports: [NgIcon],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    "[class]": "classes()",
    "[attr.aria-label]": "label()",
    "[attr.title]": "label()",
    "[attr.disabled]": "inactive() ? '' : null",
    "[attr.aria-busy]": "loading() ? 'true' : null",
    "[attr.aria-disabled]": "inactive() ? 'true' : null",
  },
  template: `
    <ng-icon
      aria-hidden="true"
      size="1rem"
      [svg]="loading() ? spinner : icon()"
      [class.animate-spin]="loading()"
      [class.motion-reduce:animate-none]="loading()"
    />
  `,
})
export class KoIconButton {
  readonly icon = input.required<string>();
  readonly label = input.required<string>();
  readonly variant = input<ButtonVariants["variant"]>("ghost");
  readonly size = input<"icon" | "icon-sm">("icon-sm");
  readonly loading = input(false, { transform: booleanAttribute });
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly class = input<string>("");

  protected readonly spinner = lucideLoaderCircle;
  protected readonly inactive = computed(() => this.disabled() || this.loading());
  protected readonly classes = computed(() =>
    cn(
      buttonVariants({ variant: this.variant(), size: this.size() }),
      this.loading() && "disabled:!opacity-100",
      this.class(),
    ),
  );
}

import { cva } from "class-variance-authority";

/**
 * The button's shapes. Kept beside `button.tsx` rather than inside it, so a test can
 * read the classes without rendering, and so the .tsx exports only components.
 */
export const buttonVariants = cva(
  "relative inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-[color,background-color,box-shadow,opacity] duration-150 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40 aria-disabled:pointer-events-none aria-disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        secondary:
          "bg-secondary text-secondary-foreground shadow-[var(--shadow-border)] hover:shadow-[var(--shadow-border-hover)]",
        outline: "bg-transparent text-foreground shadow-[var(--shadow-border)] hover:bg-secondary",
        ghost: "text-muted-foreground hover:bg-secondary hover:text-foreground",
        destructive: "bg-destructive text-white hover:bg-destructive/90",
        link: "text-foreground underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-3",
        sm: "h-8 px-2.5 text-xs",
        lg: "h-10 px-4",
        icon: "size-9 p-0",
        "icon-sm": "size-8 p-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

import { expect, it } from "vitest";
import { buttonVariants } from "./button-variants";

it("uses consistent compact geometry across visual variants", () => {
  for (const variant of ["default", "secondary", "outline", "ghost", "destructive"] as const) {
    const classes = buttonVariants({ variant });
    expect(classes).toContain("h-9");
    expect(classes).toContain("rounded-md");
    expect(classes).toContain("gap-2");
    expect(classes).not.toContain("scale-");
  }
});

import { ChangeDetectionStrategy, Component, provideZonelessChangeDetection } from "@angular/core";
import { TestBed } from "@angular/core/testing";
import { lucideRefreshCw, lucideSave } from "@ng-icons/lucide";
import { KoButton, KoIconButton } from "@/ui/primitives/button.component";

/**
 * Type-check note: `<button koIconButton>` without `label` (or `icon`) does not compile, because
 * both are `input.required()`. There is nothing to assert at runtime, and a test that compiles
 * bad code would break the build, so that case is covered by the type checker alone.
 */
@Component({
  selector: "ko-button-host",
  imports: [KoButton, KoIconButton],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <button id="saving" koButton [icon]="icon" [loading]="true">Save record</button>
    <button id="continue" koButton [loading]="true">Continue</button>
    <!-- eslint-disable-next-line @angular-eslint/template/elements-content -->
    <button id="refresh" koIconButton [icon]="refresh" label="Refresh connections"></button>
    <a id="assets" koButton href="/assets" [disabled]="true">Assets</a>
    <button id="plain" koButton class="h-12">Plain</button>
    <button id="tabbed" koButton tabindex="3">Tabbed</button>
    <a id="tabbed-link" koButton href="/x" tabindex="2">Tabbed link</a>
    <!-- eslint-disable-next-line @angular-eslint/template/elements-content -->
    <button id="busy-icon" koIconButton label="Sync" [icon]="refresh" [loading]="true"></button>
    <!-- eslint-disable-next-line @angular-eslint/template/elements-content -->
    <button id="off-icon" koIconButton label="Stop" [icon]="refresh" [disabled]="true"></button>
  `,
})
class HostComponent {
  protected readonly icon = lucideSave;
  protected readonly refresh = lucideRefreshCw;
}

describe("KoButton", () => {
  let root: HTMLElement;
  const el = (id: string) => root.querySelector<HTMLElement>(`#${id}`)!;

  beforeEach(async () => {
    TestBed.configureTestingModule({ providers: [provideZonelessChangeDetection()] });
    const fixture = TestBed.createComponent(HostComponent);
    await fixture.whenStable();
    root = fixture.nativeElement;
  });

  it("keeps the label and shows a spinner in place of the icon while loading", () => {
    const button = el("saving");
    expect(button.hasAttribute("disabled")).toBe(true);
    expect(button.getAttribute("aria-busy")).toBe("true");
    expect(button.querySelectorAll("svg")).toHaveLength(1);
    expect(button.innerHTML).toContain("animate-spin");
    expect(button.textContent).toContain("Save record");
    expect(button.textContent).not.toContain("Saving");
  });

  it("hides the label with opacity, not visibility, when loading without an icon", () => {
    const button = el("continue");
    expect(button.textContent).toContain("Continue");
    expect(button.querySelector(".opacity-0")?.textContent).toContain("Continue");
    expect(button.querySelector(".invisible")).toBeNull();
    expect(button.querySelectorAll("svg")).toHaveLength(1);
  });

  it("names an icon button from its label", () => {
    const button = el("refresh");
    expect(button.getAttribute("aria-label")).toBe("Refresh connections");
    expect(button.getAttribute("title")).toBe("Refresh connections");
    expect(button.classList).toContain("size-8");
    expect(button.querySelectorAll("svg")).toHaveLength(1);
  });

  it("disables an anchor with aria-disabled and no tab stop", () => {
    const link = el("assets");
    expect(link.tagName).toBe("A");
    expect(link.getAttribute("aria-disabled")).toBe("true");
    expect(link.getAttribute("tabindex")).toBe("-1");
    expect(link.querySelector("button")).toBeNull();
  });

  it("merges a consumer class over the variant classes", () => {
    const button = el("plain");
    expect(button.classList).toContain("h-12");
    expect(button.classList).not.toContain("h-9");
  });

  it("keeps a consumer tabindex when enabled, and drops the tab stop on a disabled anchor", () => {
    expect(el("tabbed").getAttribute("tabindex")).toBe("3");
    expect(el("tabbed-link").getAttribute("tabindex")).toBe("2");
    expect(el("assets").getAttribute("tabindex")).toBe("-1");
  });

  it("gives an icon button loading and disabled states", () => {
    const busy = el("busy-icon");
    expect(busy.getAttribute("aria-busy")).toBe("true");
    expect(busy.hasAttribute("disabled")).toBe(true);
    expect(busy.innerHTML).toContain("animate-spin");
    expect(busy.querySelectorAll("svg")).toHaveLength(1);
    expect(el("off-icon").hasAttribute("disabled")).toBe(true);
    expect(el("refresh").hasAttribute("disabled")).toBe(false);
  });
});
